async function pinHash(pin,salt=null){if(!crypto?.subtle)throw new Error(t('pinBrowserNeed'));const bytes=salt?Uint8Array.from(salt.match(/../g),x=>parseInt(x,16)):crypto.getRandomValues(new Uint8Array(16));const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:bytes,iterations:100000,hash:'SHA-256'},key,256);const hex=a=>[...a].map(n=>n.toString(16).padStart(2,'0')).join('');return{salt:hex(bytes),hash:hex(new Uint8Array(bits))};}
