function littleMissionCard(task,w){
 const can=C.taskPermission(w,task,actor,C.iso()).allowed&&(isAdult()||actor.memberId===task.memberId);
 return `<button type="button" class="little-mission ${task.status==='done'?'is-done':''}" data-action="task-toggle" data-id="${esc(task.id)}" data-week="${w.id}" ${can?'':'disabled'} aria-pressed="${task.status==='done'}" aria-label="${esc(task.title)}"><span class="little-mission-icon">${icon(task.icon)}</span><span class="little-mission-title">${esc(task.title)}</span><span class="little-mission-check">${icon(task.status==='done'?'check':'plus')}</span></button>`;
}
function renderLittleSpace(m){
 const w=current(),day=C.iso();
 const tasks=w.tasks.filter(x=>x.memberId===m.id&&C.taskOnDay(x,day)&&!(state.settings.homaRules&&x.autoPresence&&x.status==='excused')).sort((a,b)=>(a.status==='done')-(b.status==='done'));
 const routines=state.routines.filter(r=>r.active!==false&&r.memberId===m.id);
 return `<div class="child-ux little-space"><header class="little-hello">${avatar(m,'large')}<div><p class="eyebrow">${esc(t('littleHelloEyebrow'))}</p><h1>${esc(t('littleHello',{name:m.name}))}</h1></div></header><section><h2 class="little-section">${esc(t('littleMissions'))}</h2><div class="little-mission-grid">${tasks.map(x=>littleMissionCard(x,w)).join('')||`<p class="little-empty">${esc(t('littleNoMissions'))}</p>`}</div></section><section class="mt"><h2 class="little-section">${esc(t('littleRoutines'))}</h2><div class="little-routine-grid">${routines.map(r=>`<button type="button" class="little-routine" data-action="v2-routine-run" ${vattr(r.id)}><span class="little-mission-icon">${esc(r.icon)}</span><span class="little-mission-title">${esc(r.title)}</span></button>`).join('')||`<p class="little-empty">${esc(t('littleNoRoutines'))}</p>`}</div></section></div>`;
}
function renderMemberV2(){const m=member(ui.memberId);if(m.role==='pet')return renderMember();if(!isAdult()&&ui.memberId===actor.memberId){const band=childUxBand(m);if(band==='toddler')return renderToddlerSpace(m);if(band==='little')return renderLittleSpace(m);}return renderMember()+((isAdult()||ui.memberId===actor.memberId)?`<div class="context-toolbar mt">${btn(esc(t('seeWallet')),'v2-wallet-person',vattr(ui.memberId),'secondary','wallet')}${btn(esc(t('seeRoutines')),'nav','data-view="routines"','secondary','sun')}</div>`:'');}
