 if(a==='menu-shopping'){const plans=state.mealPlan.filter(p=>p.date>=ui.menuStart&&p.date<=C.addDays(ui.menuStart,6));if(!plans.length)toast(t('addDishFirst'));else shoppingPreview(plans);return true;}
 if(a==='recipe-shopping'){const r=state.recipes.find(r=>r.id===d.id),n=Number($('#recipe-servings')?.value)||r.servings;if(!Number.isInteger(n)||n<1||n>30)throw new Error(t('pickServings1to30'));shoppingPreview([{recipeId:r.id,servings:n}]);return true;}
