async function restorePrompt(next,recovery=false){const assetBundle=next.assetBundle||[];next=C.copy(next);delete next.assetBundle;C.validateState(next);openModal(recovery?t('recoverPrevCopy'):t('restoreThisFamily'),`<p class="dialog-description">${esc(t('familyColon'))} <strong>${esc(next.settings.familyName)}</strong><br>${esc(t('restoreStats',{members:next.members.length,weeks:next.weeks.length,recipes:next.recipes.length}))}</p><div class="note warning">${esc(t('restoreReplaceNote'))} ${esc(recovery?t('restoreKeepCorrupt'):t('restoreDownloadFirst'))} ${esc(t('restorePinNote'))}</div><label class="check-label align-top mt"><input type="checkbox" name="confirmRestore" required><span>${esc(t('restoreUnderstand'))}</span></label>${footer(t('restoreCopyBtn'))}`,async()=>{
  const oldState=state,oldIssue=storageIssue,oldLast=lastSavedJSON;
  try{const oldBundle=await window.HomaAssets.exportBundle(KEY,state.eventFiles.map(x=>x.id));const newIds=new Set(next.eventFiles.map(x=>x.id));if(assetBundle.length)await window.HomaAssets.importBundle(KEY,assetBundle);for(const id of newIds)if(!await window.HomaAssets.get(KEY,id))throw new Error(t('backupMissingFiles'));downloadFile('la-homa-antes-de-restaurar-'+C.iso()+'.json',corruptRaw||JSON.stringify({...state,assetBundle:oldBundle},null,2),'application/json');const imported=C.copy(next);imported.updatedAt=new Date(Math.max(Date.now(),(Date.parse(state.updatedAt)||0)+1)).toISOString();C.rollover(imported);C.validateState(imported);const raw=JSON.stringify(imported);if(lastSavedJSON&&!storageIssue)localStorage.setItem(BACKUP,lastSavedJSON);localStorage.setItem(KEY,raw);state=imported;lastSavedJSON=raw;storageIssue='';corruptRaw=null;actor=state.settings.pin?{role:'member',memberId:activeMembers().find(m=>m.role==='member')?.id||activeMembers()[0].id}:{role:'adult',memberId:null};try{sessionStorage.removeItem(KEY+'-profile');}catch(_){}ui.view='home';ui.selectedWeek=current().id;ui.historyWeek=null;ui.taskPerson='all';render();window.FPAccess?.queueSave?.(C.copy(state));toast('Copia restaurada correctamente.');return true;}
  catch(e){state=oldState;storageIssue=oldIssue;lastSavedJSON=oldLast;throw new Error(t('restoreFailed')+' '+e.message);}
 });}
$('#backup-file').addEventListener('change',async e=>{if(!needAdult())return;const file=e.target.files[0];if(!file)return;try{if(file.size>25000000)throw new Error(t('backupTooBig'));const next=C.validateState(JSON.parse(await file.text()));restorePrompt(next);}catch(err){toast(err.message||t('invalidBackup'),true);}});
$('#calendar-file').addEventListener('change',async e=>{if(!needAdult())return;const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error(t('fileOver2mb'));const parsed=C.parseICS(await file.text());if(parsed.events.length>5000)throw new Error(t('importMax5000'));if(!parsed.events.length){toast(t('noCompatibleEvents',{n:parsed.skipped}),true);return;}const updates=parsed.events.filter(e=>state.events.some(x=>(x.icsUid||x.id+'@familypoints.local')===e.icsUid)).length;confirmDialog(t('importPlansQ'),t('importPlansBody',{neu:parsed.events.length-updates,upd:updates,skip:parsed.skipped}),()=>transact(s=>{for(const e of parsed.events){const found=s.events.find(x=>(x.icsUid||x.id+'@familypoints.local')===e.icsUid);if(found)Object.assign(found,e,{id:found.id});else s.events.push(e);}},t('calendarImported',{n:parsed.skipped})),t('importEvents'));}catch(err){toast(err.message||t('calendarImportFail'),true);}});
