 if(a.startsWith('access-')||a==='v3-account')return accessAction(a,d,el);
 if(a==='v3-kitchen-return'){closeModal();ui.kitchenActive=true;ui.view='kitchen';ui.kitchenMember=null;actor={role:'member',memberId:activeMembers().find(m=>m.role==='member')?.id||activeMembers()[0]?.id};sessionStorage.setItem(KEY+'-profile',JSON.stringify(actor));render();return true;}
 if(a==='v2-kitchen-back'){if(isAdult())nav('home');else{ui.kitchenMember=null;render();}return true;}
 if(a==='v2-kitchen-person'){const role=state.members.find(m=>m.id===d.id)?.role;if(role==='adult'){toast(t('adultProfileToast'));return true;}if(role==='pet'){toast(t('petsTabletToast'));return true;}}
